(function(G){'use strict';
const H=G.HONRO_CONTENT,C=G.HONRO_CORE,W=3400,HH=1380;
const icons={forest:'funeral',temple:'hermitage',gate:'fortress',river:'ferry',valley:'gorge',bridge:'bridge',tree:'godtree',shrine:'guardian',camp:'brazier',training:'range'};
const cols={forest:'#b7b99d',temple:'#a7bbb4',gate:'#c1b38e',river:'#8fb7ba',valley:'#aab49d',bridge:'#c8ae82',tree:'#b8c28d',shrine:'#c1a0a9',camp:'#d6bb87',training:'#9fc1ba'};
const line=(d,c='#b6aa88',w=4,op=.6,dash='12 11')=>`<path d="${d}" fill="none" stroke="${c}" stroke-width="${w}" opacity="${op}" stroke-dasharray="${dash}" stroke-linecap="round"/>`;
function mountain(x,y,h){return `<path d="M${x-h*.7} ${y}Q${x-h*.25} ${y-h*.35} ${x} ${y-h}Q${x+h*.18} ${y-h*.4} ${x+h*.7} ${y}Z" fill="#263936" stroke="#87958a" stroke-opacity=".28" stroke-width="2"/>`;}
function house(x,y,s=.65){return `<g transform="translate(${x} ${y}) scale(${s})" fill="none" stroke="#b3aa8d" stroke-opacity=".42" stroke-width="5"><path d="M-44 10V-36H44V10M-58-36Q0-75 58-36"/><path d="M-10 10V-15H10V10"/></g>`;}
function art(){let s=`<svg class="world-art" viewBox="0 0 ${W} ${HH}" xmlns="http://www.w3.org/2000/svg" aria-hidden="true"><defs><linearGradient id="bg" x2="0" y2="1"><stop stop-color="#101d22"/><stop offset="1" stop-color="#09161b"/></linearGradient><linearGradient id="land" x2=".7" y2="1"><stop stop-color="#3d4945"/><stop offset="1" stop-color="#273936"/></linearGradient></defs><rect width="${W}" height="${HH}" fill="url(#bg)"/><path d="M110 230Q520 70 930 190Q1360 40 1770 145Q2180 20 2570 205Q3070 95 3310 355L3330 1165Q2860 1300 2340 1200Q1780 1340 1300 1190Q720 1320 170 1120Z" fill="url(#land)" stroke="#74847a" stroke-opacity=".55" stroke-width="3"/>`;
 for(const [x,y,h]of [[260,500,210],[430,430,250],[610,520,190],[790,410,170],[1670,315,170],[1840,285,225],[2010,345,170]])s+=mountain(x,y,h);
 s+=line('M1940 110Q1880 285 1780 395Q1600 555 1420 620Q1240 690 1080 790Q935 900 820 1210','#71999a',36,.5,'');
 s+=line('M1940 110Q1880 285 1780 395Q1600 555 1420 620Q1240 690 1080 790Q935 900 820 1210','#c1d4c9',3,.35,'');
 for(const [x,y,sc]of [[1420,820,.7],[1510,860,.6],[1990,850,.65],[2250,850,.62],[2450,810,.66],[2620,690,.62],[2790,535,.62],[2970,365,.7]])s+=house(x,y,sc);
 s+=`<g transform="translate(1070 820)" stroke="#b7aa89" stroke-opacity=".45" fill="none"><path d="M-85 28H85M-62 28V-8M-20 28V-8M22 28V-8M64 28V-8" stroke-width="7"/><path d="M-30 60Q0 75 30 60L40 43H-40Z" stroke-width="4"/></g>`;
 s+=`<g transform="translate(2040 825)" stroke="#b8a27c" stroke-opacity=".5" fill="none"><path d="M-95 0H-18M25 0H95" stroke-width="11"/><path d="M-18 0l40 20" stroke-width="5"/></g>`;
 s+=`<path d="M1840 270Q1810 345 1795 425" stroke="#c4d9d5" stroke-width="12" opacity=".5"/><path d="M2330 820Q2500 740 2680 650T3060 340" stroke="#a05f60" stroke-width="3" opacity=".30"/>`;
 for(const st of H.stages)for(const id of st.requires){const q=H.stages[id-1],mx=(q.map[0]+st.map[0])/2,my=Math.min(q.map[1],st.map[1])-55;s+=line(`M${q.map[0]} ${q.map[1]}Q${mx} ${my} ${st.map[0]} ${st.map[1]}`,'#d0bd94',4,.72);}
 const c=H.stages[2];s+=line(`M${c.map[0]} ${c.map[1]}Q1190 970 ${H.hubs[0].x} ${H.hubs[0].y}`,'#cbb58c',3,.48);s+=line(`M${H.hubs[0].x} ${H.hubs[0].y}Q1010 1180 ${H.hubs[1].x} ${H.hubs[1].y}`,'#9fbab3',3,.45);
 s+=`<g fill="#d0c4a5" opacity=".68" font-family="Batang,serif" letter-spacing="5"><text x="245" y="165" font-size="30">북쪽 고갯길</text><text x="880" y="960" font-size="27">연목 나루</text><text x="1370" y="1040" font-size="30">연목 마을</text><text x="1670" y="150" font-size="26">폭포 절벽</text><text x="2690" y="170" font-size="27">윗마당</text></g><text x="160" y="1280" fill="#d9c9a6" font-family="Batang,serif" font-size="40" letter-spacing="8" opacity=".8">첫째 막 · 연목의 매듭</text></svg>`;return s;}
function markup(profile,stageId,hub,header){return `<main class="screen map-screen atlas-screen">${header}<section class="atlas-shell"><div class="atlas-viewport" id="map-scroll" tabindex="0"><div class="map-board" id="map-board" style="width:${W}px;height:${HH}px">${art()}${H.stages.map(st=>{const open=st.requires.every(x=>profile.cleared[x]),done=!!profile.cleared[st.id],sel=st.id===stageId&&!hub;return `<button class="map-node honro-node ${open?'open':'locked'} ${done?'cleared':''} ${sel?'selected':''} node-${st.theme}" data-action="map-node" data-id="${st.id}" data-map-x="${st.map[0]}" data-map-y="${st.map[1]}" style="left:${st.map[0]}px;top:${st.map[1]}px;--landmark:${cols[st.theme]}" aria-label="${st.id}번 · ${st.name}${open?'':' · 닫힌 길'}"><span class="stage-index">${String(st.id).padStart(2,'0')}</span><span class="atlas-pin">${C.icon(icons[st.theme],'',27)}</span><span class="atlas-node-caption">${st.name}</span>${done?'<i class="route-done">✓</i>':''}</button>`;}).join('')}${H.hubs.map(h=>`<button class="atlas-hub hub-${h.id} ${h.id===hub?'selected':''}" data-action="map-hub" data-id="${h.id}" data-map-x="${h.x}" data-map-y="${h.y}" style="left:${h.x}px;top:${h.y}px;--hub-color:${cols[h.id]}" aria-label="${h.name}"><span class="hub-emblem">${C.icon(icons[h.id],'',24)}</span><span class="hub-label"><strong>${h.name}</strong></span></button>`).join('')}</div></div><div class="atlas-tools"><button class="icon-btn" data-action="map-fit" aria-label="전체 지도">${C.icon('map','',18)}</button><button class="icon-btn" data-action="map-home" aria-label="현재 길목">${C.icon('target','',18)}</button><span id="atlas-zoom"></span><button class="icon-btn" data-action="map-in" aria-label="확대">+</button><button class="icon-btn" data-action="map-out" aria-label="축소">−</button></div></section><div class="map-dock" id="map-dock"></div></main>`;}
G.HonroJourney={markup,icons,cols};
})(globalThis);
